from flask import Flask, render_template_string

app = Flask(__name__)

HTML = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Electrical Warehouse</title>
<style>
*{box-sizing:border-box}:root{--bg:#eef2f3;--panel:#f8faf9;--ink:#34454b;--muted:#718087;--line:#ccd7d8;--accent:#527d83;--soft:#e0ebea}
body{margin:0;font-family:Arial,Helvetica,sans-serif;background:var(--bg);color:var(--ink)}header{background:#536a70;color:#f8fbfb;padding:14px 20px}.top{max-width:1250px;margin:auto;display:flex;justify-content:space-between;align-items:center;gap:12px}h1{margin:0;font-size:clamp(18px,2.4vw,25px)}.lang{display:flex;gap:5px;flex-wrap:wrap}.lang button,.back,.save{border:1px solid var(--line);border-radius:8px;padding:8px 10px;cursor:pointer}.workspace{max-width:1250px;margin:auto;padding:18px 14px;display:grid;grid-template-columns:145px 1fr;gap:18px}.side{display:flex;flex-direction:column;align-items:center;gap:12px}.diamond-button{width:112px;height:112px;border:0;background:transparent;cursor:pointer}.diamond{width:80px;height:80px;margin:16px auto;background:#f7faf9;border:2px solid var(--line);border-radius:13px;transform:rotate(45deg);display:flex;align-items:center;justify-content:center}.diamond-inner{width:108px;transform:rotate(-45deg);text-align:center;font-weight:700;font-size:12px;line-height:1.05;overflow-wrap:anywhere}.icon{display:block;font-size:19px;margin-bottom:2px}.content{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:22px;min-width:0}.page{display:none}.page.active{display:block}.subtitle{color:var(--muted)}.box{border:1px solid var(--line);border-radius:12px;padding:20px;background:#fff;min-height:350px}.machine-grid,.section-grid{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:12px}.machine,.section-tile,.detail-tile,.fault-main{min-height:78px;border:1px solid var(--line);border-radius:10px;background:#f2f6f5;color:var(--ink);font-weight:700;cursor:pointer;padding:9px;font-size:13px;line-height:1.15;white-space:normal;overflow-wrap:anywhere;text-align:center}.machine:hover,.section-tile:hover,.detail-tile:hover,.fault-main:hover{background:var(--soft);border-color:var(--accent)}.fault-main{width:min(240px,100%);min-height:82px;margin:4px 0 20px;background:#e8f1ef;font-size:15px}.detail-grid{display:grid;grid-template-columns:repeat(2,minmax(180px,1fr));gap:16px;max-width:620px}.detail-tile{min-height:105px}.section-info{margin-top:18px;padding:16px;border:1px solid var(--line);border-radius:12px;background:#fff}.fault-form{margin-top:18px;padding:16px;border:1px solid var(--line);border-radius:12px;background:#fff}.fault-form label{display:block;font-weight:700;margin:12px 0 5px}.fault-form input,.fault-form textarea,.fault-form select{width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;background:#fbfdfc}.fault-form textarea{min-height:70px}.save{margin-top:14px;background:var(--accent);color:white;font-weight:700}.records{margin-top:18px;display:grid;gap:10px}.record{background:#fff;border:1px solid var(--line);border-radius:10px;padding:12px}.record img{max-width:180px;max-height:130px;border-radius:8px;margin-top:8px}.record-date{font-weight:700}.stats{margin:15px 0;padding:10px;background:var(--soft);border-radius:8px;font-weight:700}
html[dir="rtl"] .workspace{direction:rtl}html[dir="rtl"] .side,html[dir="rtl"] .content{direction:rtl}html[dir="rtl"] .lang{direction:ltr}
@media(max-width:900px){.machine-grid,.section-grid{grid-template-columns:repeat(3,minmax(110px,1fr))}.machine,.section-tile{font-size:12px}}
@media(max-width:720px){.workspace{grid-template-columns:105px 1fr;gap:8px;padding:10px 6px}.diamond-button{width:92px;height:92px}.diamond{width:64px;height:64px}.diamond-inner{width:92px;font-size:10px}.content{padding:14px 10px}.machine-grid,.section-grid{grid-template-columns:repeat(2,minmax(92px,1fr));gap:8px}.machine,.section-tile{font-size:11px;min-height:68px;padding:6px}.detail-grid{grid-template-columns:1fr}h1{font-size:18px}.lang button{font-size:11px;padding:6px 7px}}
</style></head><body>
<header><div class="top"><h1>⚡ <span id="appTitle"></span></h1><div class="lang"><button onclick="setLang('ru')">RU</button><button onclick="setLang('he')">עברית</button><button onclick="setLang('en')">EN</button></div></div></header>
<main class="workspace"><nav class="side"><button class="diamond-button" id="stockBtn" onclick="showPage('stock')"><div class="diamond"><div class="diamond-inner"><span class="icon">📦</span><span id="stockNav"></span></div></div></button><button class="diamond-button" id="machinesBtn" onclick="showPage('machines')"><div class="diamond"><div class="diamond-inner"><span class="icon">🏭</span><span id="machinesNav"></span></div></div></button></nav><section class="content">
<div id="stock" class="page active"><h2 id="stockTitle"></h2><div class="box" id="stockBox"></div></div>
<div id="machines" class="page"><h2 id="machinesTitle"></h2><p class="subtitle" id="machinesSub"></p><div class="machine-grid" id="machineGrid"></div></div>
<div id="thermoPage" class="page"><button class="back" onclick="showPage('machines')" id="thermoBack"></button><h2 id="thermoTitle"></h2><p class="subtitle" id="thermoSub"></p><button class="fault-main" id="thermoFaults" onclick="openThermoFaults()"></button><div class="section-grid" id="thermoGrid"></div></div>
<div id="thermoSectionPage" class="page"><button class="back" onclick="openThermo(currentMachineIndex)" id="thermoSectionBack"></button><h2 id="thermoSectionTitle"></h2><div class="section-info"><b id="thermoPartsTitle"></b><p id="thermoPartsText"></p></div></div>
<div id="machineDetail" class="page"><button class="back" onclick="showPage('machines')" id="backBtn"></button><h2 id="machineDetailTitle"></h2><div class="detail-grid"><button class="detail-tile" id="faultsTile" onclick="openGenericFaults()"></button><button class="detail-tile" id="partsTile"></button></div></div>
<div id="extruderPage" class="page"><button class="back" onclick="showPage('machines')" id="extruderBack"></button><h2 id="extruderTitle"></h2><p class="subtitle" id="extruderSub"></p><div class="section-grid" id="extruderGrid"></div></div>
<div id="extruderSectionPage" class="page"><button class="back" onclick="openExtruder(currentMachineIndex)" id="sectionBack"></button><h2 id="sectionTitle"></h2><div class="detail-grid"><button class="detail-tile" id="sectionFaults" onclick="openExtruderFaults()"></button><button class="detail-tile" id="sectionParts"></button></div></div>
<div id="faultPage" class="page"><button class="back" onclick="backFromFaults()" id="faultBack"></button><h2 id="faultTitle"></h2><div class="stats" id="stats"></div><div class="fault-form"><label id="dateLabel"></label><input type="date" id="faultDate"><label id="areaLabel"></label><select id="faultAreaSelect"></select><input id="faultAreaInput" style="display:none"><label id="faultLabel"></label><textarea id="faultText"></textarea><label id="repairLabel"></label><textarea id="repairText"></textarea><label id="replaceLabel"></label><input id="replaceText"><label id="photoLabel"></label><input type="file" accept="image/*" capture="environment" id="faultPhoto"><button class="save" onclick="saveFault()" id="saveBtn"></button></div><div class="records" id="records"></div></div>
</section></main>
<script>
let lang=localStorage.getItem('elektrikaLang')||'ru',currentMachineIndex=null,currentExtruderSection=null,currentThermoSection=null,faultMode='generic';
const machines={ru:['Кефель 5','Кефель 6','Кефель 7','Кефель 8','Кефель 9','Кефель 10','Кефель 11','Кефель 12','Кефель 13','C1','C2','C3','RDM','Машина печати','Машина формовки стаканов','Экструдер 4','Экструдер 5','Экструдер 6'],he:['כפל 5','כפל 6','כפל 7','כפל 8','כפל 9','כפל 10','כפל 11','כפל 12','כפל 13','C1','C2','C3','RDM','מכונת דפוס','מכונת כוסות','אקסטרודר 4','אקסטרודר 5','אקסטרודר 6'],en:['Kefel 5','Kefel 6','Kefel 7','Kefel 8','Kefel 9','Kefel 10','Kefel 11','Kefel 12','Kefel 13','C1','C2','C3','RDM','Printing Machine','Cup Forming Machine','Extruder 4','Extruder 5','Extruder 6']};
const thermoSections={ru:['Размотка','Цепной транспорт / подача пластика','Нагрев','Формовка','Нож / резка','Робот и выгрузка','Электрошкаф A','Электрошкаф B'],he:['פריסה','שרשרת והזנת פלסטיק','חימום','תרמופורמינג','סכין / חיתוך','רובוט ופריקה','לוח חשמל A','לוח חשמל B'],en:['Unwinding','Chain transport / plastic feed','Heating','Thermoforming','Knife / cutting','Robot and unloading','Electrical Cabinet A','Electrical Cabinet B']};
const extruderSections={ru:['Станция дозирования','Экструдер A — главный','Экструдер B — вспомогательный','Каландр','Станция силикона','Ресивер','Узел намотки'],he:['תחנת מינון','אקסטרודר A — ראשי','אקסטרודר B — משני','קלנדר','תחנת סיליקון','רסיבר','גלילן'],en:['Dosing Station','Extruder A — Main','Extruder B — Secondary','Calender','Silicone Station','Receiver','Winding Unit']};
const T={ru:{title:'Электрический склад',stock:'Общий склад',machines:'Машины',choose:'Выберите машину',back:'← Назад к машинам',faults:'Поломки',parts:'Электрические части',faultBack:'← Назад',date:'Дата поломки',area:'Часть машины',fault:'Какая поломка',repair:'Что сделал / ремонт',replace:'Замена электрической детали',photo:'Фотография поломки',save:'Сохранить поломку',stats:'Всего сохранённых поломок',extruderSub:'Выберите часть экструзионной линии',sectionBack:'← Назад к экструдеру',thermoSub:'Выберите станцию машины',thermoSectionBack:'← Назад к машине',partsTitle:'Электрические части этой станции',partsText:'Здесь будем хранить моторы, датчики, нагреватели, приводы, модели и другие электрические компоненты этой станции.',stockText:'Здесь будем отдельно строить общий склад.'},he:{title:'מחסן חשמל',stock:'מחסן כללי',machines:'מכונות',choose:'בחר מכונה',back:'← חזרה למכונות',faults:'תקלות',parts:'חלקי חשמל',faultBack:'← חזרה',date:'תאריך התקלה',area:'חלק במכונה',fault:'מה התקלקל',repair:'מה עשיתי / תיקון',replace:'החלפת חלק חשמלי',photo:'תמונה של התקלה',save:'שמור תקלה',stats:'סה״כ תקלות שמורות',extruderSub:'בחר חלק מקו האקסטרוזיה',sectionBack:'← חזרה לאקסטרודר',thermoSub:'בחר תחנה במכונה',thermoSectionBack:'← חזרה למכונה',partsTitle:'חלקי החשמל של התחנה',partsText:'כאן נשמור מנועים, חיישנים, גופי חימום, דרייבים, דגמים ורכיבים חשמליים של התחנה.',stockText:'כאן נבנה את המחסן הכללי.'},en:{title:'Electrical Warehouse',stock:'General Warehouse',machines:'Machines',choose:'Select a machine',back:'← Back to machines',faults:'Faults',parts:'Electrical Parts',faultBack:'← Back',date:'Fault date',area:'Machine section',fault:'Fault description',repair:'What was done / repair',replace:'Electrical part replaced',photo:'Fault photo',save:'Save fault',stats:'Saved faults',extruderSub:'Select a section of the extrusion line',sectionBack:'← Back to extruder',thermoSub:'Select a machine station',thermoSectionBack:'← Back to machine',partsTitle:'Electrical parts for this station',partsText:'Here we will store motors, sensors, heaters, drives, models and other electrical components for this station.',stockText:'Here we will build the general warehouse.'}};
function showPage(p){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(p).classList.add('active')}
function makeMachines(){machineGrid.innerHTML='';machines[lang].forEach((n,i)=>{let b=document.createElement('button');b.className='machine';b.textContent=n;b.onclick=()=>openMachine(i);machineGrid.appendChild(b)})}
function openMachine(i){currentMachineIndex=i;currentExtruderSection=null;currentThermoSection=null;if(i<=11)return openThermo(i);if(i>=15)return openExtruder(i);machineDetailTitle.textContent=machines[lang][i];showPage('machineDetail')}
function openThermo(i){currentMachineIndex=i;currentThermoSection=null;thermoTitle.textContent=machines[lang][i];thermoSub.textContent=T[lang].thermoSub;thermoGrid.innerHTML='';thermoSections[lang].forEach((n,idx)=>{let b=document.createElement('button');b.className='section-tile';b.textContent=n;b.onclick=()=>openThermoSection(idx);thermoGrid.appendChild(b)});showPage('thermoPage')}
function openThermoSection(idx){currentThermoSection=idx;thermoSectionTitle.textContent=machines[lang][currentMachineIndex]+' — '+thermoSections[lang][idx];thermoPartsTitle.textContent=T[lang].partsTitle;thermoPartsText.textContent=T[lang].partsText;showPage('thermoSectionPage')}
function openExtruder(i){currentMachineIndex=i;currentExtruderSection=null;extruderTitle.textContent=machines[lang][i];extruderSub.textContent=T[lang].extruderSub;extruderGrid.innerHTML='';extruderSections[lang].forEach((n,idx)=>{let b=document.createElement('button');b.className='section-tile';b.textContent=n;b.onclick=()=>openExtruderSection(idx);extruderGrid.appendChild(b)});showPage('extruderPage')}
function openExtruderSection(idx){currentExtruderSection=idx;sectionTitle.textContent=machines[lang][currentMachineIndex]+' — '+extruderSections[lang][idx];sectionFaults.textContent=T[lang].faults;sectionParts.textContent=T[lang].parts;showPage('extruderSectionPage')}
function openThermoFaults(){faultMode='thermo';faultAreaSelect.style.display='block';faultAreaInput.style.display='none';faultAreaSelect.innerHTML='';thermoSections[lang].forEach(n=>faultAreaSelect.add(new Option(n,n)));openFaultPage()}
function openGenericFaults(){faultMode='generic';faultAreaSelect.style.display='none';faultAreaInput.style.display='block';openFaultPage()}
function openExtruderFaults(){faultMode='extruder';faultAreaSelect.style.display='none';faultAreaInput.style.display='block';faultAreaInput.value=extruderSections[lang][currentExtruderSection];openFaultPage()}
function openFaultPage(){faultTitle.textContent=machines[lang][currentMachineIndex]+' — '+T[lang].faults;faultDate.value=todayLocal();renderRecords();showPage('faultPage')}
function backFromFaults(){if(faultMode==='thermo')openThermo(currentMachineIndex);else if(faultMode==='extruder')showPage('extruderSectionPage');else showPage('machineDetail')}
function todayLocal(){let d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function key(){if(faultMode==='thermo')return 'faults_machine_'+currentMachineIndex;if(faultMode==='extruder')return 'faults_machine_'+currentMachineIndex+'_section_'+currentExtruderSection;return 'faults_machine_'+currentMachineIndex}
function areaValue(){return faultMode==='thermo'?faultAreaSelect.value:faultAreaInput.value}
function saveFault(){let file=faultPhoto.files[0];let finish=photo=>{let a=JSON.parse(localStorage.getItem(key())||'[]');a.unshift({date:faultDate.value,area:areaValue(),fault:faultText.value,repair:repairText.value,replace:replaceText.value,photo:photo||''});try{localStorage.setItem(key(),JSON.stringify(a))}catch(e){alert('Storage is full. Use a smaller photo.');return}faultText.value='';repairText.value='';replaceText.value='';faultPhoto.value='';renderRecords()};if(file){let r=new FileReader();r.onload=e=>finish(e.target.result);r.readAsDataURL(file)}else finish('')}
function esc(s){let d=document.createElement('div');d.textContent=s||'';return d.innerHTML}
function renderRecords(){let a=JSON.parse(localStorage.getItem(key())||'[]');stats.textContent=T[lang].stats+': '+a.length;records.innerHTML='';a.forEach(x=>{let d=document.createElement('div');d.className='record';d.innerHTML='<div class="record-date">'+esc(x.date)+'</div><div><b>'+T[lang].area+':</b> '+esc(x.area)+'</div><div><b>'+T[lang].fault+':</b> '+esc(x.fault)+'</div><div><b>'+T[lang].repair+':</b> '+esc(x.repair)+'</div><div><b>'+T[lang].replace+':</b> '+esc(x.replace)+'</div>'+(x.photo?'<img src="'+x.photo+'">':'');records.appendChild(d)})}
function rerenderCurrent(){if(document.getElementById('thermoPage').classList.contains('active'))openThermo(currentMachineIndex);else if(document.getElementById('thermoSectionPage').classList.contains('active'))openThermoSection(currentThermoSection);else if(document.getElementById('extruderPage').classList.contains('active'))openExtruder(currentMachineIndex);else if(document.getElementById('extruderSectionPage').classList.contains('active'))openExtruderSection(currentExtruderSection);else if(document.getElementById('machineDetail').classList.contains('active')&&currentMachineIndex!==null){machineDetailTitle.textContent=machines[lang][currentMachineIndex]}else if(document.getElementById('faultPage').classList.contains('active')){if(faultMode==='thermo'){let old=faultAreaSelect.selectedIndex;openThermoFaults();faultAreaSelect.selectedIndex=Math.max(0,old)}else if(faultMode==='extruder'){openExtruderFaults()}else openGenericFaults()}}
function setLang(l){lang=l;localStorage.setItem('elektrikaLang',l);let t=T[l];document.documentElement.lang=l;document.documentElement.dir=l==='he'?'rtl':'ltr';document.title=t.title;appTitle.textContent=t.title;stockNav.textContent=t.stock;machinesNav.textContent=t.machines;stockTitle.textContent=t.stock;stockBox.textContent=t.stockText;machinesTitle.textContent=t.machines;machinesSub.textContent=t.choose;thermoBack.textContent=t.back;thermoFaults.textContent=t.faults;thermoSectionBack.textContent=t.thermoSectionBack;backBtn.textContent=t.back;faultsTile.textContent=t.faults;partsTile.textContent=t.parts;extruderBack.textContent=t.back;sectionBack.textContent=t.sectionBack;sectionFaults.textContent=t.faults;sectionParts.textContent=t.parts;faultBack.textContent=t.faultBack;dateLabel.textContent=t.date;areaLabel.textContent=t.area;faultLabel.textContent=t.fault;repairLabel.textContent=t.repair;replaceLabel.textContent=t.replace;photoLabel.textContent=t.photo;saveBtn.textContent=t.save;makeMachines();rerenderCurrent()}
setLang(lang);
</script></body></html>'''

@app.route('/')
def home(): return render_template_string(HTML)

if __name__ == '__main__': app.run(debug=True)
